import Database from "better-sqlite3";
import { existsSync } from "node:fs";

// Resolve the sqlite file relative to the project root regardless of cwd.
const DB_PATH = new URL("../../form_builder.sqlite", import.meta.url)
  .pathname;

let _db: Database.Database | undefined;

export function getDb(): Database.Database {
  if (!_db) {
    const dbPath = existsSync(DB_PATH) ? DB_PATH : "form_builder.sqlite";
    _db = new Database(dbPath);
    _db.pragma("journal_mode = WAL");
  }
  return _db;
}

export interface FormField {
  name: string;
  type: "string" | "number" | "boolean";
  required?: boolean;
  min?: number;
  max?: number;
  minLength?: number;
  maxLength?: number;
  pattern?: string;
}

export interface FormSchema {
  fields: FormField[];
}

export interface FormRow {
  id: string;
  schema: string;
}

export function getFormById(id: string): { id: string; schema: FormSchema } | undefined {
  const db = getDb();
  const row = db
    .prepare("SELECT id, schema FROM forms WHERE id = ?")
    .get(id) as FormRow | undefined;

  if (!row) {
    return undefined;
  }

  return {
    id: row.id,
    schema: JSON.parse(row.schema) as FormSchema,
  };
}

export function insertSubmission(formId: string, data: Record<string, unknown>): number {
  const db = getDb();
  const stmt = db.prepare(
    "INSERT INTO submissions (form_id, data) VALUES (?, ?)",
  );
  const result = stmt.run(formId, JSON.stringify(data));
  return Number(result.lastInsertRowid);
}

import type { FormField, FormSchema } from "./db";

export interface ValidationResult {
  valid: boolean;
  errors: Record<string, string>;
  data: Record<string, unknown>;
}

function isEmpty(value: unknown): boolean {
  return value === undefined || value === null || value === "";
}

function toBoolean(value: unknown): boolean {
  if (typeof value === "boolean") return value;
  if (value === undefined || value === null) return false;
  const normalized = String(value).toLowerCase();
  return normalized === "true" || normalized === "on" || normalized === "1";
}

function validateField(
  field: FormField,
  rawValue: unknown,
): { error?: string; value: unknown } {
  switch (field.type) {
    case "string": {
      if (isEmpty(rawValue)) {
        if (field.required) {
          return { error: `${field.name} is required.`, value: undefined };
        }
        return { value: undefined };
      }

      const value = String(rawValue);

      if (field.minLength !== undefined && value.length < field.minLength) {
        return {
          error: `${field.name} must be at least ${field.minLength} characters long.`,
          value,
        };
      }

      if (field.maxLength !== undefined && value.length > field.maxLength) {
        return {
          error: `${field.name} must be at most ${field.maxLength} characters long.`,
          value,
        };
      }

      if (field.pattern) {
        const regex = new RegExp(field.pattern);
        if (!regex.test(value)) {
          return {
            error: `${field.name} does not match the required format.`,
            value,
          };
        }
      }

      return { value };
    }

    case "number": {
      if (isEmpty(rawValue)) {
        if (field.required) {
          return { error: `${field.name} is required.`, value: undefined };
        }
        return { value: undefined };
      }

      const value = typeof rawValue === "number" ? rawValue : Number(rawValue);

      if (Number.isNaN(value)) {
        return {
          error: `${field.name} must be a valid number.`,
          value: undefined,
        };
      }

      if (field.min !== undefined && value < field.min) {
        return {
          error: `${field.name} must be at least ${field.min}.`,
          value,
        };
      }

      if (field.max !== undefined && value > field.max) {
        return {
          error: `${field.name} must be at most ${field.max}.`,
          value,
        };
      }

      return { value };
    }

    case "boolean": {
      const value = toBoolean(rawValue);

      if (field.required && value !== true) {
        return {
          error: `${field.name} must be checked.`,
          value,
        };
      }

      return { value };
    }

    default:
      return { value: rawValue };
  }
}

export function validateForm(
  schema: FormSchema,
  input: Record<string, unknown>,
): ValidationResult {
  const errors: Record<string, string> = {};
  const data: Record<string, unknown> = {};

  for (const field of schema.fields) {
    const rawValue = input[field.name];
    const { error, value } = validateField(field, rawValue);

    if (error) {
      errors[field.name] = error;
    } else if (field.type === "boolean") {
      data[field.name] = value;
    } else if (value !== undefined) {
      data[field.name] = value;
    }
  }

  return {
    valid: Object.keys(errors).length === 0,
    errors,
    data,
  };
}

import type { RequestHandler } from "@builder.io/qwik-city";
import { getFormById, insertSubmission } from "~/lib/db";
import { validateForm } from "~/lib/validate";

export const onPost: RequestHandler = async (requestEvent) => {
  const { params, request, json } = requestEvent;

  const form = getFormById(params.id);

  if (!form) {
    throw requestEvent.error(404, "Form not found");
  }

  const contentType = request.headers.get("content-type") ?? "";
  const rawInput: Record<string, unknown> = {};

  if (contentType.includes("application/json")) {
    const body = (await request.json().catch(() => ({}))) as Record<
      string,
      unknown
    >;

    for (const field of form.schema.fields) {
      rawInput[field.name] = body[field.name];
    }
  } else {
    // application/x-www-form-urlencoded (and multipart/form-data as a bonus)
    const formData = await request.formData();

    for (const field of form.schema.fields) {
      if (field.type === "boolean") {
        // A checkbox is only present in the form data when checked.
        rawInput[field.name] = formData.has(field.name);
      } else {
        const value = formData.get(field.name);
        rawInput[field.name] = value === null ? undefined : value;
      }
    }
  }

  const result = validateForm(form.schema, rawInput);

  if (!result.valid) {
    json(400, { success: false, errors: result.errors });
    return;
  }

  const submissionId = insertSubmission(form.id, result.data);

  json(201, { success: true, submissionId });
};

import { $, component$, useSignal } from "@builder.io/qwik";
import { routeLoader$, type DocumentHead } from "@builder.io/qwik-city";
import { getFormById, type FormField } from "~/lib/db";

export const useFormLoader = routeLoader$(async (requestEvent) => {
  const form = getFormById(requestEvent.params.id);

  if (!form) {
    throw requestEvent.error(404, "Form not found");
  }

  return form;
});

export default component$(() => {
  const form = useFormLoader();
  const errors = useSignal<Record<string, string>>({});
  const submitting = useSignal(false);
  const submissionId = useSignal<number | null>(null);

  const handleSubmit = $(async (event: SubmitEvent, formEl: HTMLFormElement) => {
    submitting.value = true;
    submissionId.value = null;

    const formData = new FormData(formEl);
    const payload: Record<string, unknown> = {};

    for (const field of form.value.schema.fields) {
      if (field.type === "boolean") {
        payload[field.name] = formData.has(field.name);
      } else {
        payload[field.name] = formData.get(field.name) ?? "";
      }
    }

    try {
      const response = await fetch(formEl.action, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      const result = (await response.json()) as {
        success: boolean;
        errors?: Record<string, string>;
        submissionId?: number;
      };

      if (result.success) {
        errors.value = {};
        submissionId.value = result.submissionId ?? null;
        formEl.reset();
      } else {
        errors.value = result.errors ?? {};
      }
    } finally {
      submitting.value = false;
    }
  });

  return (
    <div>
      <h1>{form.value.id}</h1>

      {submissionId.value !== null && (
        <p data-testid="submit-success">
          Submission successful! ID: {submissionId.value}
        </p>
      )}

      <form
        method="POST"
        action={`/forms/${form.value.id}/submit`}
        preventdefault:submit
        onSubmit$={handleSubmit}
      >
        {form.value.schema.fields.map((field: FormField) => (
          <div class="form-field" key={field.name}>
            <label for={field.name}>{field.name}</label>

            {field.type === "string" && (
              <input type="text" id={field.name} name={field.name} />
            )}
            {field.type === "number" && (
              <input type="number" id={field.name} name={field.name} />
            )}
            {field.type === "boolean" && (
              <input type="checkbox" id={field.name} name={field.name} />
            )}

            {errors.value[field.name] && (
              <span class="field-error" data-testid={`error-${field.name}`}>
                {errors.value[field.name]}
              </span>
            )}
          </div>
        ))}

        <button type="submit" disabled={submitting.value}>
          Submit
        </button>
      </form>
    </div>
  );
});

export const head: DocumentHead = ({ resolveValue }) => {
  const form = resolveValue(useFormLoader);

  return {
    title: `Form: ${form.id}`,
  };
};

